const urlParams = new URLSearchParams(window.location.search);

// {{gclid}} SEM ASPAS de proposito: entre aspas o Typebot manda o ID da variavel.
const cid = String({{gclid}} || {{gbraid}} || {{wbraid}}
  || urlParams.get('gclid') || urlParams.get('gbraid') || urlParams.get('wbraid') || '');

const nome = String({{nome}} || '');
const doc  = String({{cpf}} || '');

const parts = [];
if (cid) {
  parts.push('src=' + encodeURIComponent(cid));
  // utm_content = CARRIER: o webhook do TopperPay nao tem campo src, mas devolve os utm_*.
  parts.push('utm_content=' + encodeURIComponent(cid));
} else if (urlParams.has('utm_content')) {
  parts.push('utm_content=' + encodeURIComponent(urlParams.get('utm_content')));
}
['utm_source', 'utm_medium', 'utm_campaign', 'utm_term'].forEach(k => {
  if (urlParams.has(k)) parts.push(k + '=' + encodeURIComponent(urlParams.get(k)));
});
if (nome) parts.push('name=' + encodeURIComponent(nome));
if (doc)  parts.push('document=' + encodeURIComponent(doc));

const query = parts.join('&');
// checkout PROPRIO desta oferta: produto "Imposto IOF" R$ 45,00 (PIX), salesPage meubeneficio.sbs/chat/
window.location.href = 'https://pay.asegupag.com/checkout/f8e9949c-04a7-475e-8876-806f252b8fa2' + (query ? '?' + query : '');
